        case 3: return .syncProgress(walletHeight: try FfiConverterUInt32.read(from: &buf), networkHeight: try FfiConverterUInt32.read(from: &buf), percent: try FfiConverterFloat.read(from: &buf)
        )
        
        case 4: return .syncPaused
        
        case 5: return .syncFinished
        
        case 6: return .balanceChanged(try FfiConverterTypeBalanceSnapshot.read(from: &buf)
        )
        
        case 7: return .newTransaction(txid: try FfiConverterString.read(from: &buf)
        )
        
        case 8: return .error(code: try FfiConverterString.read(from: &buf), message: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: WalletEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case .engineReady:
            writeInt(&buf, Int32(1))
        
        
        case .syncStarted:
            writeInt(&buf, Int32(2))
        
        
        case let .syncProgress(walletHeight,networkHeight,percent):
            writeInt(&buf, Int32(3))
            FfiConverterUInt32.write(walletHeight, into: &buf)
            FfiConverterUInt32.write(networkHeight, into: &buf)
            FfiConverterFloat.write(percent, into: &buf)
            
        
        case .syncPaused:
            writeInt(&buf, Int32(4))
        
        
        case .syncFinished:
            writeInt(&buf, Int32(5))
        
        
        case let .balanceChanged(v1):
            writeInt(&buf, Int32(6))
            FfiConverterTypeBalanceSnapshot.write(v1, into: &buf)
            
        
        case let .newTransaction(txid):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(txid, into: &buf)
            
        
        case let .error(code,message):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


